/**
 * T46 perf pass: measures the client on the real build.
 *
 *   1. desktop Chromium: ms from `goto()` to the first drawn game frame, default art vs `?art=svg`
 *   2. iPhone 13 (WebKit, landscape) bot match: 20 s of live FPS samples, plus the lowfx watchdog
 *      state and the particle peak
 *
 * Numbers go to stdout and `.loop/perf.md` (regenerated by every run, not committed).
 */
import { execSync } from 'node:child_process';
import fs from 'node:fs';
import { chromium, webkit, devices } from '@playwright/test';
import { startServer } from './lib/temp-server.mjs';

const PORT = 8723;
const RUNS = 3;
const MATCH_MS = 20_000;

const median = (xs) => [...xs].sort((a, b) => a - b)[Math.floor(xs.length / 2)];

/** Time from navigation start to the first GameScene.update (the hook records performance.now()). */
async function firstFrame(browser, query) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 720 } });
  await ctx.addInitScript(() => localStorage.setItem('brawl.tutorial', 'seen'));
  const page = await ctx.newPage();
  const t0 = Date.now();
  await page.goto(`http://127.0.0.1:${PORT}/?room=perf-${Math.random().toString(36).slice(2, 8)}&bots=1${query}`);
  await page.waitForFunction(
    () => Boolean(window.__brawl?.fps?.firstFrameMs),
    null,
    { timeout: 30_000, polling: 16 },
  );
  const hook = await page.evaluate(() => window.__brawl.fps);
  const ms = Date.now() - t0;
  await ctx.close();
  return { wall: ms, hookMs: hook.firstFrameMs };
}

/** A 20 s bot match on the phone profile: sample FPS once a second. */
async function phoneMatch(browser) {
  const d = devices['iPhone 13'];
  const landscape = { width: d.viewport.height, height: d.viewport.width };
  const ctx = await browser.newContext({ ...d, viewport: landscape, screen: landscape });
  await ctx.addInitScript(() => localStorage.setItem('brawl.tutorial', 'seen'));
  const page = await ctx.newPage();
  await page.goto(`http://127.0.0.1:${PORT}/?room=perfph-${Math.random().toString(36).slice(2, 8)}&bots=3&tide=high`);
  await page.waitForFunction(() => Boolean(window.__brawl?.fps?.firstFrameMs), null, { timeout: 30_000 });
  const samples = [];
  let peak = 0;
  const until = Date.now() + MATCH_MS;
  while (Date.now() < until) {
    await page.waitForTimeout(1000);
    const p = await page.evaluate(() => window.__brawl.fps);
    samples.push(p.fps);
    peak = Math.max(peak, p.particles);
  }
  const end = await page.evaluate(() => window.__brawl.fps);
  await ctx.close();
  return { samples, lowfx: end.lowfx, peak, firstFrameMs: end.firstFrameMs };
}

execSync('npm run build', { stdio: 'ignore', env: { ...process.env, OUT_DIR: 'dist/test-client' } });
const stop = await startServer(PORT, { CLIENT_DIR: 'dist/test-client' });
let chromiumBrowser;
let webkitBrowser;
try {
  chromiumBrowser = await chromium.launch();
  const plain = [];
  const svg = [];
  for (let i = 0; i < RUNS; i++) {
    plain.push(await firstFrame(chromiumBrowser, ''));
    svg.push(await firstFrame(chromiumBrowser, '&art=svg'));
  }
  await chromiumBrowser.close();
  chromiumBrowser = null;

  webkitBrowser = await webkit.launch();
  const phone = await phoneMatch(webkitBrowser);

  const p3d = median(plain.map((r) => r.wall));
  const psvg = median(svg.map((r) => r.wall));
  const fpsMin = Math.min(...phone.samples);
  const fpsMedian = median(phone.samples);
  const lines = [
    `desktop first frame: 3D ${p3d} ms (${plain.map((r) => r.wall).join('/')}) · SVG ${psvg} ms (${svg.map((r) => r.wall).join('/')})`,
    `iPhone 13 20 s bot match: fps median ${fpsMedian}, min ${fpsMin} (${phone.samples.join(' ')})`,
    `lowfx watchdog tripped: ${phone.lowfx ? 'YES' : 'no'} · particle peak ${phone.peak}`,
  ];
  fs.mkdirSync('.loop', { recursive: true });
  fs.writeFileSync('.loop/perf.md', `# T46 perf (${new Date().toISOString()})\n${lines.join('\n')}\n`);
  console.log(lines.join('\n'));
} finally {
  await chromiumBrowser?.close();
  await webkitBrowser?.close();
  await stop();
}
